    return [entry.type, entry.cornerstone ? '基石只读' : '可更新', entry.focus ? '主焦点' : '', entry.constant ? '常驻' : '关键词触发', entry.vectorized ? '远端向量' : '', entry.recursable ? '可递归' : '不参与递归'].filter(Boolean).join(' · ');
